    /**
     * Method to retrieve the Regulation via RegulationFetchOneSummary
     * @param 	summary RegulationFetchOneSummary 
     * @return 	RegulationFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Regulation getRegulation( RegulationFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "RegulationFetchOneSummary arg cannot be null" );
    	
    	Regulation entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Regulation
        	// --------------------------------------
        	CompletableFuture<Regulation> futureEntity = queryGateway.query(new FindRegulationQuery( new LoadRegulationFilter( summary.getRegulationId() ) ), ResponseTypes.instanceOf(Regulation.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Regulation with id " + summary.getRegulationId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


